public static int SumDigits(string s)
{
    Span<int> buf = stackalloc int[16];
    int n = 0;
    foreach (char c in s.AsSpan())
        if (char.IsDigit(c) && n < buf.Length)
            buf[n++] = c - '0';

    int sum = 0;
    foreach (int d in buf[..n]) sum += d;
    return sum;
}

