using System.Buffers;
using System.Runtime.CompilerServices;

// Буфер из пула. Memory, а не Span: Span нельзя держать через await
static async Task<long> CountBytesAsync(Stream s, CancellationToken ct)
{
    byte[] buf = ArrayPool<byte>.Shared.Rent(64 * 1024);
    try
    {
        long total = 0;
        int read;
        while ((read = await s.ReadAsync(buf.AsMemory(), ct)) > 0)
            total += read;
        return total;
    }
    finally
    {
        ArrayPool<byte>.Shared.Return(buf);
    }
}

// Строки приходят по одной, как только прочитаны
static async IAsyncEnumerable<string> ReadLinesAsync(
    string path, [EnumeratorCancellation] CancellationToken ct = default)
{
    using var reader = new StreamReader(path);
    while (await reader.ReadLineAsync(ct) is { } line)
        yield return line;
}

// Не больше 5 секунд на всё чтение
using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(5));
await foreach (var line in ReadLinesAsync("log.txt", cts.Token))
    Console.WriteLine(line);

