using System.Collections.Concurrent;

// Контекст с одним потоком, как у окна WPF или WinForms
SynchronizationContext.SetSynchronizationContext(new OneThreadContext());

Task<int> task = GetAsync();
// .Result висел бы вечно, Wait с таймаутом - чтобы это увидеть
Console.WriteLine(task.Wait(2000) ? $"готово: {task.Result}" : "hung");

static async Task<int> GetAsync()
{
    await Task.Delay(100);   // продолжение просится обратно в контекст
    return 42;
}

// Продолжения копятся в очереди. Разбирать её должен главный поток,
// но он стоит в Wait.
sealed class OneThreadContext : SynchronizationContext
{
    private readonly BlockingCollection<(SendOrPostCallback, object?)> _queue = new();
    public override void Post(SendOrPostCallback d, object? state)
        => _queue.Add((d, state));
}

